      #   traits: []
      #   outfit: []
      #   action: []
      #   body_parts_visible: []
    entities: ["{{tag1}}", "{{tag2}}", "..."]  # Objects/buildings/creatures, e.g. lantern / castle / black cat
    background: ["{{tag1}}", "{{tag2}}", "..."]  # Background scene lighting, e.g. flower field / sunset / backlight / best shadow
